def solve(tokens):
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division truncating toward zero
                # Python's int division with // floors toward -inf, so use int(a / b)
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(t))
    return stack[-1]

