    """Count the number of islands in a binary grid.
    An island is a group of adjacent cells with value 1, connected
    orthogonally (up, down, left, right).
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
