def solve(tokens):
    """Evaluate Reverse Polish Notation tokens.
    Supports integer tokens given as strings or integers. Handles division
    truncating toward zero. If division by zero occurs, returns 0.
    """
    stack = []
    for t in tokens:
        # allow integer tokens directly
        if isinstance(t, int):
            stack.append(t)
            continue
        if t in ('+', '-', '*', '/'):
            if len(stack) < 2:
                # malformed expression; return 0
                return 0
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division
                if b == 0:
                    return 0
                # truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            # treat as integer convertible token
            try:
                stack.append(int(t))
            except Exception:
                # invalid token, ignore
                pass
    return stack[0] if stack else 0

