def solve(grid):
    """Count islands in a binary grid that may be jagged.
    Cells with value 1 are connected orthogonally (up, down, left, right).
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def neighbors(r, c):
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for nx, ny in neighbors(x, y):
                if (nx, ny) not in visited and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    count = 0
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and (r, c) not in visited:
                dfs(r, c)
                count += 1
    return count

