def solve(matrix):
    """Return elements of matrix in clockwise spiral order.
    Handles empty matrix and non-rectangular rows by treating missing
    cells as absent (only traverses existing elements).
    """
    if not matrix:
        return []
    # Determine bounds based on actual dimensions
    top, bottom = 0, len(matrix) - 1
    left, right = 0, max(len(row) for row in matrix) - 1
    result = []
    visited = set()
    total = sum(len(row) for row in matrix)
    while len(result) < total:
        # move right across top row
        for col in range(left, right + 1):
            if top < len(matrix) and col < len(matrix[top]) and (top, col) not in visited:
                result.append(matrix[top][col])
                visited.add((top, col))
        top += 1
        # move down the right column
        for row in range(top, bottom + 1):
            if row < len(matrix) and right < len(matrix[row]) and (row, right) not in visited:
                result.append(matrix[row][right])
                visited.add((row, right))
        right -= 1
        # move left across bottom row
        if top <= bottom:
            for col in range(right, left - 1, -1):
                if bottom < len(matrix) and col < len(matrix[bottom]) and (bottom, col) not in visited:
                    result.append(matrix[bottom][col])
                    visited.add((bottom, col))
            bottom -= 1
        # move up the left column
        if left <= right:
            for row in range(bottom, top - 1, -1):
                if row < len(matrix) and left < len(matrix[row]) and (row, left) not in visited:
                    result.append(matrix[row][left])
                    visited.add((row, left))
            left += 1
    return result

